,CAEAgH,MAAMG,GAAN,GAEA,IAAI,GAAI1C,GAAE,CAAV,CAAaA,GAAGyC,CAAhB,CAAmBzC,GAAnB,CAAwB,CACtB,GAAI2C,MAAOJ,MAAMvC,CAAN,CAAX,CACA,GAAG,CAAC2C,IAAD,EAASA,KAAK,CAAL,GAAW,GAAvB,CAA4B,CAC1B,QACD,CACD,GAAIpF,MAAOqF,KAAKC,KAAL,CAAWF,KAAK5E,OAAL,CAAa,IAAb,CAAmB,KAAnB,EAA4B,GAAvC,CAAX,CAEA,GAAIR,KAAKV,OAAT,CAAkB,CAChBZ,UAAUqE,SAAV,CAAoBkB,MAApB,CAA2BjE,KAAKV,OAAhC,EACAZ,UAAUY,OAAV,EAAqB,GAEtB,CAJD,IAIO,IAAGU,KAAKuF,WAAR,CAAqB,CAC1B7G,UAAUwE,MAAV,CAAmBlD,KAAKuF,WAAxB,CACA7G,UAAU0E,QAAV,CAAmBvC,IAAnB,CAAwB,uBAAyBzE,OAAOY,IAAP,CAAYmD,IAAZ,CAAiBqF,SAA1C,CAAqD,WAA7E,CACD,CACF,CACF,CAAC,MAAMpI,CAAN,CAAS,CACTmE,QAAQF,KAAR,CAAcjE,CAAd,CACD,CACF,CACJ,CAlCM,CAJK,CAAP,CAAb,CA0CA;AACAkH,OAAOmB,IAAP,CAAY,SAASzF,IAAT,CAAe,CACzB,GAAG,CAACtB,UAAUY,OAAd,CAAuB,CACrBZ,UAAUqE,SAAV,CAAoBlC,IAApB,CAAyB,6BAA+BzE,OAAOY,IAAP,CAAYmD,IAAZ,CAAiBuF,eAAhD,CAAkE,gDAAlE,CAAqHtJ,OAAOY,IAAP,CAAYmD,IAAZ,CAAiBwF,cAAtI,CAAuJ,YAAhL,EACA,MACD,CAEDjH,UAAUyE,WAAV,CAAsBnC,IAAtB,GACA,GAAI,CACFoD,eAAiBwB,WAAW,UAAU,CACpCrE,QAAQsE,IAAR,CAAa,cAAb,EAEA,GAAGnH,UAAUsE,IAAV,EAAkB,GAAlB,EAAyBtE,UAAUuE,WAAV,CAAsBS,IAAlD,CAAwD,CACtDhF,UAAUiF,WAAV,CACEjF,UAAUsE,IADZ,CAEEtE,UAAUuE,WAAV,CAAsBQ,OAAtB,EAAiC,KAFnC,CAGE/E,UAAUuE,WAAV,CAAsBS,IAAtB,EAA8B,KAHhC,CAKD,CACF,CAVgB,CAWlB,CAAC,MAAMtG,CAAN,CAAS,CACTmE,QAAQF,KAAR,CAAcjE,CAAd,CACD,CACF,CAtBD,EAuBAkH,OAAOwB,MAAP,CAAc,SAAS9F,IAAT,CAAe,CAC3B4F,WAAW,UAAU,CACnBnJ,EAAE,kBAAF,EAAsB0C,MAAtB,EACD,CAFD,CAEG,CAFH,CAGD,CAJD,EAKAmF,OAAOyB,IAAP,CAAY,SAASzE,GAAT,CAAa,CACvB,GAAGA,IAAI0E,UAAJ,EAAkB,CAAlB,EAAuB1E,IAAIE,MAAJ,EAAc,CAAxC,CAA2C,CAAE;AAC3C,MACD,CACD,GAAGF,IAAIE,MAAJ,EAAc,GAAjB,CAAsB,CACpB9C,UAAUqE,SAAV,CAAoBlC,IAApB,CAAyB,4BAA8BzE,OAAOY,IAAP,CAAYmD,IAAZ,CAAiB8F,SAA/C,CAA2D,iCAA3D,CAA+F7J,OAAOY,IAAP,CAAYmD,IAAZ,CAAiB+F,KAAhH,CAAwH,YAAjJ,CACD,CAFD,IAEO,CACLxH,UAAUqE,SAAV,CAAoBlC,IAApB,CAAyB,4BAA8BzE,OAAOY,IAAP,CAAYmD,IAAZ,CAAiBkB,KAA/C,CAAuD,QAAhF,EACAE,QAAQa,GAAR,CAAY,SAAZ,CAAuBd,GAAvB,CACD,CACF,CAVD,CAWD,CApJa,CAAhB","file":"app.js","sourcesContent":["\nvar process = process || {};\nprocess.env = process.env || {};\n\nwindow.MEMLIKE = window.MEMLIKE || {};\nwindow.MEMLIKE.js_app = {\n  build_date: "2026-07-06T11:44+02:00",\n};\n\n/* global $, window, document, console, navigator */\n/* global setTimeout, URL, Blob */\n$(document).ready(function(){\n  window.$_GET = window.getUrlParameters();\n  Object.freeze(window.I18N);\n  Object.freeze(window.$_GET);\n\n  if(window.MEMLIKE.page) {\n    Object.freeze(window.MEMLIKE.page);\n  }\n  window.defineMarkdown();\n\n  // Show/hide elements\n  $('h2[data-toggle]').on('click', function(e){\n    $($(this).attr('data-toggle')).toggleClass('hide');\n  });\n  $('button[data-toggle]').on('click', function(e){\n    var $target = $($(this).attr('data-toggle')).fadeIn();\n\n    // Give focus to the target\n    if ($target.prop('nodeName') == 'FORM') {\n      $target.get(0).originToggle = this;\n\n      $('button', $target).first().focus();\n    }\n  });\n  $('#mode-selector').on('click', '.mode-selector-close', function(e){\n    var $target = $(e.delegateTarget).fadeOut();\n\n    var originToggle = $target.get(0).originToggle;\n    if (originToggle) {\n      $(originToggle).focus();\n    }\n  });\n\n  // Page /courses events\n  if($('#courses-container').length) {\n    courses();\n    categories();\n  }\n\n  // Audio tag toggle play/pause\n  if($('#course-container, #learn-container').length) {\n    window.audioPlayer.init();\n    window.imgZoom.init();\n    window.multimedia.init();\n  }\n\n  // Page /user event\n  if($('#user-container').length) {\n    user_mempals();\n    user_courses();\n    user_progress_things();\n  }\n\n  // Dashboard\n  if($('#dashboard').length) {\n    Dashboard.init();\n  }\n\n  // Sync\n  $('.ajax[data-href]').on('click', function(){\n    if(this.classList.contains('loading-spinner-before')) {\n      return;\n    }\n    var btn = this;\n    btn.classList.add('loading-spinner-before');\n\n    $.ajax({\n      url: btn.getAttribute('data-href'),\n      complete: function(){\n        btn.classList.remove('loading-spinner-before');\n        window.location.reload();\n      }\n    });\n  });\n});\n\n//+--------------------------------------------------------\n//| Browse courses using AJAX\n//+--------------------------------------------------------\nfunction courses() {\n  var content  = $('#courses-container'),\n      paging   = $('#content-loader').children();\n\n  _paginate('/ajax/courses', {\n      lang: window.MEMLIKE.page.currentLang,\n      cat : window.MEMLIKE.page.currentCat,\n      q   : window.$_GET.q\n  }, (window.$_GET.q ? '?q=' + encodeURIComponent(window.$_GET.q) : ''), content, paging, function(data, current_page) {\n    if(data.content.trim() == '' && current_page == 1) {\n      return '<div class=\"empty-box\"><p>' + window.I18N.misc.courses_none + '</p></div>';\n    } else {\n      return data.content;\n    }\n  });\n}\n\n/**\n * @param string ajax_url\n * @param Object data          - POST parameters\n * @parma string q             - query string to keep when changing page\n * @param JqueryObject content - container\n * @param JqueryObject paging  - pagination\n * @param function tpl         - callback to format response to HTML\n */\nfunction _paginate(ajax_url, data, q, content, paging, tpl) {\n  var url      = window.location.href.replace(/[?#].*/, ''),\n  current_page = parseInt(window.$_GET.page) || 1,\n  has_next     = true;\n\n  if(q) {\n    q += '&';\n  } else {\n    q = '?';\n  }\n  function query(page, pushState) {\n    content.html('');\n    paging.hide().filter('.paging-loader').show();\n\n    data.page = page;\n    $.ajax({\n      url: ajax_url,\n      data: data,\n      success: function(data) {\n        var lastpage = data.lastpage || 0;\n\n        has_next     = data.has_next;\n        current_page = page;\n\n        content.html(tpl(data, current_page));\n        paging.hide();\n\n        if(current_page == 1) {\n          paging.filter('.prev').hide();\n        } else {\n          if(lastpage && current_page > 2) {\n            paging.filter('.first').show()\n                .attr('href', q + 'page=' + 1)\n                .find('.page').html(window.I18N.misc.page.replace('%', 1));\n          }\n          paging.filter('.prev').show()\n                .attr('href', q + 'page=' + (current_page - 1))\n                .find('.page').html(window.I18N.misc.page.replace('%', current_page - 1));\n        }\n\n        if(has_next) {\n          if(lastpage && current_page + 1 < lastpage) {\n            paging.filter('.last').show()\n                .attr('href', q + 'page=' + lastpage)\n                .find('.page').html(window.I18N.misc.page.replace('%', lastpage));\n          }\n          paging.filter('.next')\n                .attr('href', q + 'page=' + (current_page + 1))\n                .show().find('.page').html(window.I18N.misc.page.replace('%', current_page + 1));\n        } else {\n          paging.filter('.next').hide();\n        }\n\n        if(pushState) {\n          window.history.pushState({ page: current_page, has_next: has_next }, '', url + q + 'page=' + current_page);\n        }\n      },\n      error: function(xhr) {\n        console.error(xhr.status + ' ' + xhr.statusText);\n\n        content.html(window.I18N.misc.error);\n        paging.hide();\n      }\n    });\n  }\n\n  $(window).on('popstate', function(event) {\n      var state = event.originalEvent.state;\n\n      if(state && state.page) {\n          query(state.page, false);\n      }\n  });\n\n  paging.filter('.next').on('click', function(e){\n    e.preventDefault();\n\n    if(has_next) {\n      query(current_page + 1, true);\n    }\n  });\n\n  paging.filter('.prev').on('click', function(e){\n    e.preventDefault();\n\n    if(current_page > 1) {\n      query(current_page - 1, true);\n    }\n  });\n\n  query(current_page, true);\n}\n\n//+--------------------------------------------------------\n//| Show/hide child categories\n//+--------------------------------------------------------\nfunction categories() {\n  if(window.MEMLIKE.page.currentCatId) {\n    $('.categories-list a.active')\n      .parents('li[data-category-id]')\n      .addClass('open');\n  }\n  $('.categories-list').on('click', 'li:has(> ul)', function(e){\n    if($(e.target).is('a[data-category-leaf]')) {\n      return;\n    }\n\n    e.preventDefault();\n    e.stopPropagation();\n    console.log(e);\n\n    $(this).toggleClass('open');\n  });\n}\n\n//+--------------------------------------------------------\n//| User profile\n//+--------------------------------------------------------\n\n// Browse followers/following users using AJAX\nfunction user_mempals() {\n  var content  = $('#mempals-container');\n  if(!content.length) {\n    return;\n  }\n  var paging = $('#content-loader').children(),\n      tab    = content.data('tab'),\n      url    = '/ajax/user/' + window.MEMLIKE.page.username + '/' + tab;\n\n  _paginate(url, {}, '', content, paging, function(data){\n    if(!data.users.length) {\n      var msg = window.I18N.misc[tab + '_none'].replace('%', '<span class=\"grey\">' + window.MEMLIKE.page.username + '</span>');\n      return '<div class=\"empty-box\"><p>' + msg + '</p></div>';\n    }\n\n    var html = '';\n    for(var i=0; i<data.users.length; i++) {\n      html += '<a class=\"user-box\" href=\"/user/' + data.users[i].name + '\">' +\n                (data.users[i].photo ? `<div class=\"small-photo\"><img src=\"${data.users[i].photo}\" alt></div>` : '') +\n                '<span title=\"' + data.users[i].name + '\">' + data.users[i].name + '</span>'\n              + '</a>';\n    }\n    html += '<span class=\"user-box is-empty\"></span>';\n    html += '<span class=\"user-box is-empty\"></span>';\n    html += '<span class=\"user-box is-empty\"></span>';\n    return html;\n  });\n}\n\n// Browse user's courses using AJA\nfunction user_courses() {\n  var content  = $('#usercourses-container');\n  if(!content.length) {\n    return;\n  }\n  var paging = $('#content-loader').children(),\n      tab    = content.data('tab'),\n      url    = '/ajax/user/' + window.MEMLIKE.page.username + '/' + tab;\n\n  _paginate(url, {}, '', content, paging, function(data){\n    if(data.content.length == 0) {\n      return '<div class=\"empty-box\"><p>' + window.I18N.misc.courses_none + '</p></div>';\n    }\n    return data.content.join('')\n          + '<div class=\"course-box is-empty\"></div>'\n          + '<div class=\"course-box is-empty\"></div>'\n          + '<div class=\"course-box is-empty\"></div>';\n  });\n}\n\nfunction user_progress_things() {\n  var content  = $('#things-progress-container');\n  if(!content.length) {\n    return;\n  }\n  $.ajax({\n    url: '/ajax/progress',\n    success: function(rendered) {\n      let div = $('.ContributionCalendar', '<div>' + rendered + '</div>');\n      console.log(div);\n      if (div.length) {\n        content.html(div);\n      }\n    },\n    error: function(xhr) {\n      console.error(xhr.status + ' ' + xhr.statusText);\n\n      content.html(window.I18N.misc.error);\n    }\n  });\n}\n\n//+--------------------------------------------------------\n//| Dashboard\n//+--------------------------------------------------------\n\nvar Dashboard = {\n  container: false,\n  sort: 'i',\n  sortOptions: {},\n  offset: 0,\n  content: '',\n\n  init: function() {\n    Dashboard.container   = $('#dashboard');\n    Dashboard.sortActions = $('#dashboard-sort');\n    Dashboard.loadNext    = $('#content-next');\n    Dashboard.getCourses();\n\n    $(Dashboard.loadNext).on('click', '.btn', function(){\n      Dashboard.loadMore();\n    });\n\n    $('select', Dashboard.sortActions).on('change', function(){\n      var sort = this.value;\n\n      if(sort != Dashboard.sort) {\n        var option = $('option:selected', this);\n        var sortOptions = {numeric: option.attr('data-numeric'), desc: option.attr('data-desc')};\n\n        Dashboard.sort = sort;\n        Dashboard.sortOptions = sortOptions;\n        Dashboard.sortCourses(sort, sortOptions.numeric || false, sortOptions.desc || false);\n      }\n    });\n  },\n\n  sortCourses: function(sort, isNumeric, desc) {\n    var courses = Dashboard.container.children();\n\n    if(isNumeric) {\n      courses.sort(function(a, b){\n        if(desc) {\n          [b,a] = [a,b];\n        }\n        return parseFloat(a.getAttribute('data-' + sort)) - parseFloat(b.getAttribute('data-' + sort));\n      });\n    } else {\n      courses.sort(function(a, b){\n        if(desc) {\n          [b,a] = [a,b];\n        }\n        return a.getAttribute('data-' + sort).localeCompare(b.getAttribute('data-' + sort));\n      });\n    }\n    Dashboard.container.append(courses);\n  },\n\n  loadMore: function() {\n    Dashboard.loadNext.empty();\n    Dashboard.loadNext.after('<div id=\"content-loader\" class=\"loading-spinner\"></div>');\n    Dashboard.getCourses();\n  },\n\n  getCourses: function() {\n    const requestOffset = Dashboard.offset;\n    if (!requestOffset) {\n      Dashboard.content = '';\n    }\n\n    /* global $ */\n    var offsetStream = 0;\n    var runner = $.ajax({\n        url: '/ajax/dashboard?offset=' + requestOffset + '&_=' + new Date().getTime(),\n        data: {},\n        processData: false,\n        xhrFields: {\n            // Getting on progress streaming response\n            onprogress: function(e) {\n                var response = e.target.response;\n\n                if(response.substr(response.length-1, 1) == '$') {\n                  try {\n                    var r = response.substring(offsetStream);\n                    offsetStream = response.length;\n\n                    var parts = r.split('}$'),\n                        n     = parts.length - 1;\n                    parts.pop();\n\n                    for(var i=0; i<=n; i++) {\n                      var part = parts[i];\n                      if(!part || part[0] != '{') {\n                        continue;\n                      }\n                      var data = JSON.parse(part.replace('\\n', '\\\\n') + '}');\n\n                      if (data.content) {\n                        Dashboard.container.append(data.content);\n                        Dashboard.content += '.';\n\n                      } else if(data.next_offset) {\n                        Dashboard.offset = data.next_offset;\n                        Dashboard.loadNext.html('<button class=\"btn\">' + window.I18N.misc.load_more +'</button>');\n                      }\n                    }\n                  } catch(e) {\n                    console.error(e);\n                  }\n                }\n            }\n        }\n    });\n\n    // Ajax done running\n    runner.done(function(data) {\n      if(!Dashboard.content) {\n        Dashboard.container.html('<div class=\"empty-box\"><p>' + window.I18N.misc.empty_dashboard + '</p><a class=\"link\" href=\"/community/courses\">' + window.I18N.misc.browse_courses + '</a></div>');\n        return;\n      }\n\n      Dashboard.sortActions.show();\n      try {\n        requestOffset && setTimeout(function(){\n          console.info('Resorting...');\n\n          if(Dashboard.sort != 'i' || Dashboard.sortOptions.desc) {\n            Dashboard.sortCourses(\n              Dashboard.sort,\n              Dashboard.sortOptions.numeric || false,\n              Dashboard.sortOptions.desc || false,\n            );\n          }\n        });\n      } catch(e) {\n        console.error(e);\n      }\n    });\n    runner.always(function(data) {\n      setTimeout(function(){\n        $('.loading-spinner').remove();\n      }, 0);\n    });\n    runner.fail(function(xhr){\n      if(xhr.readyState == 0 || xhr.status == 0) { // request has been canceled (change page)\n        return;\n      }\n      if(xhr.status == 403) {\n        Dashboard.container.html('<div style=\"width: 100%\">' + window.I18N.misc.error_403 + ' <a class=\"link\" href=\"/login\">' + window.I18N.misc.login + '</a></div>');\n      } else {\n        Dashboard.container.html('<div style=\"width: 100%\">' + window.I18N.misc.error + '</div>');\n        console.log('Error: ', xhr);\n      }\n    });\n  }\n};\n"]}